(()=>{'use strict';const M=MartinsMateriais,P=MartinsPersistenciaRdo,D=MartinsDepositos;function actor(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null')}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!D.canManage(u)||!session||id(u)!==id(session)||session.perfil!==u.perfil||session.status==='Inativo')throw Error('Perfil não autorizado a alterar situação do material');return u.usuario||u.email||u.nome;}
async function toggle(id){try{const by=actor(),before=P.snapshot(localStorage,M.CATALOG,INITIAL_PRODUTOS_FATOR),p=before.data.find(p=>p.id===id);if(!p)throw Error('Material indisponível');const active=M.isActive(p),reason=prompt((active?'Inativar':'Reativar')+' '+p.nome+'. Informe o motivo (histórico e saldo serão preservados):');if(reason===null)return;const next=M.setActive(before.data,id,!active,reason,by);await P.withLock(navigator.locks,()=>{if(actor()!==by)throw Error('Sessão alterada');P.commit(localStorage,[{key:M.CATALOG,expected:before.raw,value:next}],{actor:by});});window.renderTabelaProdutosFator?.();window.renderEstoqueDepositosMartins?.();window.dispatchEvent(new Event('martins-produtos-atualizados'));showToast(active?'Material inativado com histórico e saldo preservados.':'Material reativado.');}catch(e){showToast(e.message,'warning');if(P.hasPending(localStorage))window.martinsMostrarRecuperacao?.();}}
const render=window.renderTabelaProdutosFator;window.renderTabelaProdutosFator=function(...args){const r=render.apply(this,args),rows=window.getProdutosFatorDb();for(const [i,tr]of [...document.querySelectorAll('#tbody-produtos-fator>tr')].entries()){const p=rows[i];if(!p)continue;const b=tr.querySelector('button');if(b){b.removeAttribute('onclick');b.onclick=()=>toggle(p.id);b.textContent=M.isActive(p)?'Inativar':'Reativar';b.title='Preservar material, saldo e histórico';}if(!M.isActive(p)){const tag=document.createElement('span');tag.textContent='INATIVO';tag.style.cssText='display:block;color:#991b1b;font-weight:bold';tr.firstElementChild.append(tag);}}return r;};
window.excluirProdutoFator=idx=>{const p=window.getProdutosFatorDb()[idx];if(p)return toggle(p.id);};const save=window.saveProdutosFatorDb;window.saveProdutosFatorDb=function(rows){const before=window.getProdutosFatorDb();if(before.some(p=>!rows.some(r=>r.id===p.id)))throw Error('Exclusão física bloqueada: inative o material para preservar o histórico');return save(rows);};
})();
